  T("{n} = completely calm · {n} = very tense", "{n} = completamente tranquilo/a · {n} = muy tenso/a", "{n} = completamente calmo(a) · {n} = muito tenso(a)", "{n} = complètement calme · {n} = très tendu(e)");
